//! R6a: learn bounded control flow from examples while reusing certified R3.
//! The teacher supplies labels only; executable source is generated by Rust.
use crate::tutor_rust_r2::{self as r2, Expr, Temp};
use crate::tutor_rust_r3 as r3;
use std::error::Error;
use std::fs;
use std::io::{Read, Write};
use std::path::Path;
use std::process::{Command, Stdio};

type Result<T> = std::result::Result<T, Box<dyn Error>>;
type Example = (u8, u8, u8);
const TASKS: usize = 4;
const TRAIN: [(u8, u8); 24] = r3::TRAIN;
const DEV: [(u8, u8); 8] = r3::DEV;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Predicate {
    Less,
    Equal,
    Even,
}

impl Predicate {
    fn eval(self, a: u8, b: u8) -> bool {
        match self {
            Self::Less => a < b,
            Self::Equal => a == b,
            Self::Even => a & 1 == 0,
        }
    }

    fn source(self) -> &'static str {
        match self {
            Self::Less => "a < b",
            Self::Equal => "a == b",
            Self::Even => "a & 1 == 0",
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Program {
    Branch(Predicate, usize, usize),
    Repeat(u8, usize),
    Sequence(usize, usize),
}

impl Program {
    fn eval(self, memory: &[Expr], a: u8, b: u8) -> u8 {
        match self {
            Self::Branch(pred, yes, no) => {
                memory[if pred.eval(a, b) { yes } else { no }].eval(a, b)
            }
            Self::Repeat(count, body) => {
                let mut x = a;
                for _ in 0..count {
                    x = memory[body].eval(x, b);
                }
                x
            }
            Self::Sequence(first, second) => {
                let x = memory[first].eval(a, b);
                memory[second].eval(x, b)
            }
        }
    }

    fn source(self) -> String {
        match self {
            Self::Branch(pred, yes, no) => format!(
                "if {} {{ saved_{yes}(a,b) }} else {{ saved_{no}(a,b) }}",
                pred.source()
            ),
            Self::Repeat(count, body) => {
                format!("let mut x=a; for _ in 0..{count} {{ x=saved_{body}(x,b); }} x")
            }
            Self::Sequence(first, second) => {
                format!("let x=saved_{first}(a,b); saved_{second}(x,b)")
            }
        }
    }
}

fn grammar() -> Vec<Program> {
    let mut programs = Vec::new();
    for pred in [Predicate::Less, Predicate::Equal, Predicate::Even] {
        for yes in 0..7 {
            for no in 0..7 {
                if yes != no {
                    programs.push(Program::Branch(pred, yes, no));
                }
            }
        }
    }
    for count in 2..=4 {
        for body in 0..7 {
            programs.push(Program::Repeat(count, body));
        }
    }
    for first in 0..7 {
        for second in 0..7 {
            programs.push(Program::Sequence(first, second));
        }
    }
    programs
}

// Independent wider-integer reference, no calls to the candidate or bank.
// Tasks deliberately have different control-flow and state-update structures.
fn oracle(task: usize, a: u8, b: u8) -> u8 {
    let (a, b) = (u32::from(a), u32::from(b));
    let y = match task {
        0 => {
            if a < b {
                (((a + b) % 256) ^ a) * b
            } else {
                (a & b) * a + b
            }
        }
        1 => {
            if a & 1 == 0 {
                (((a ^ b) + b) % 256) ^ a
            } else {
                (a.min(b) ^ b) + a
            }
        }
        2 => {
            let one = (a * (b + 1) % 256) ^ b;
            let two = (one * (b + 1) % 256) ^ b;
            (two * (b + 1) % 256) ^ b
        }
        3 => {
            let x = (((a + b) % 256) ^ a) * b % 256;
            (x - (x & b)) * b
        }
        _ => unreachable!(),
    };
    (y % 256) as u8
}

pub fn fixture() -> String {
    let mut raw = String::from("SML_TUTOR_R6A_TRAIN_V1\n");
    for task in 0..TASKS {
        for (a, b) in TRAIN {
            raw.push_str(&format!("{task}|{a}|{b}|{}\n", oracle(task, a, b)));
        }
    }
    raw
}

fn admit(raw: &str) -> Result<Vec<Vec<Example>>> {
    if raw.len() > 8192 || !raw.ends_with('\n') {
        return Err("invalid R6a corpus size or termination".into());
    }
    let mut lines = raw.lines();
    if lines.next() != Some("SML_TUTOR_R6A_TRAIN_V1") {
        return Err("invalid R6a corpus marker".into());
    }
    let mut batch = Vec::new();
    for task in 0..TASKS {
        let mut examples = Vec::new();
        for (a, b) in TRAIN {
            let row = lines.next().ok_or("missing R6a TRAIN row")?;
            if row != format!("{task}|{a}|{b}|{}", oracle(task, a, b)) {
                return Err(format!("invalid R6a teacher row task={task}, a={a}, b={b}").into());
            }
            examples.push((
                a,
                b,
                row.rsplit('|').next().ok_or("missing label")?.parse()?,
            ));
        }
        batch.push(examples);
    }
    if lines.next().is_some() {
        return Err("extra R6a TRAIN rows".into());
    }
    Ok(batch)
}

fn memory(parent: &str, child: &str) -> Result<Vec<Expr>> {
    r3::examine(parent, child)?;
    let saved = r3::verified_memory(parent, &r2::grammar())?;
    r3::restore(child, &r3::extend(&saved))
}

fn checkpoint(programs: &[Program]) -> String {
    let mut raw = String::from("SML_TUTOR_R6A_BANK_V1\n");
    for program in programs {
        raw.push_str(&program.source());
        raw.push('\n');
    }
    raw
}

fn restore(raw: &str) -> Result<Vec<Program>> {
    if raw.len() > 8192 || !raw.ends_with('\n') {
        return Err("invalid R6a bank size or termination".into());
    }
    let mut lines = raw.lines();
    if lines.next() != Some("SML_TUTOR_R6A_BANK_V1") {
        return Err("invalid R6a bank marker".into());
    }
    let candidates = grammar();
    let programs: Vec<_> = lines
        .map(|line| {
            candidates
                .iter()
                .find(|p| p.source() == line)
                .copied()
                .ok_or("unknown R6a program")
        })
        .collect::<std::result::Result<_, _>>()?;
    if programs.len() != TASKS || checkpoint(&programs) != raw {
        return Err("invalid R6a bank".into());
    }
    Ok(programs)
}

/// The old memory is an independently examined prerequisite; only admitted
/// TRAIN labels select among the 196 typed programs. Ambiguity fails closed.
pub fn induce(parent: &str, child: &str, raw: &str) -> Result<String> {
    let saved = memory(parent, child)?;
    let candidates = grammar();
    if candidates.len() != 196 || TRAIN.iter().any(|p| DEV.contains(p)) {
        return Err("R6a grammar or split contract".into());
    }
    let mut learned = Vec::new();
    for examples in admit(raw)? {
        if saved
            .iter()
            .any(|expr| examples.iter().all(|&(a, b, y)| expr.eval(a, b) == y))
        {
            return Err("old macro baseline did not abstain".into());
        }
        let mut matching = candidates
            .iter()
            .filter(|p| examples.iter().all(|&(a, b, y)| p.eval(&saved, a, b) == y));
        let chosen = *matching.next().ok_or("R6a synthesis inconsistent")?;
        if matching.next().is_some() {
            return Err("R6a synthesis ambiguous".into());
        }
        learned.push(chosen);
    }
    Ok(checkpoint(&learned))
}

fn compile(saved: &[Expr], programs: &[Program], root: &Path) -> Result<Vec<u8>> {
    let mut source =
        String::from("#![allow(unused_parens,dead_code)]\nuse std::io::{self,Write};\n");
    for (i, expr) in saved.iter().enumerate() {
        source.push_str(&format!(
            "fn saved_{i}(a:u8,b:u8)->u8{{ {} }}\n",
            expr.source()
        ));
    }
    for (i, program) in programs.iter().enumerate() {
        source.push_str(&format!(
            "fn learned_{i}(a:u8,b:u8)->u8{{ {} }}\n",
            program.source()
        ));
    }
    source.push_str("fn main()->io::Result<()> {let mut out=io::BufWriter::new(io::stdout().lock());for a in 0u8..=255{for b in 0u8..=255{out.write_all(&[");
    for i in 0..TASKS {
        source.push_str(&format!("learned_{i}(a,b),"));
    }
    source.push_str("])?;}}out.flush()}\n");
    let file = root.join("r6.rs");
    let binary = root.join("r6");
    fs::write(&file, source)?;
    let compiler = std::env::var_os("RUSTC").unwrap_or_else(|| "rustc".into());
    let result = Command::new(compiler)
        .args([
            "--edition=2021",
            "-Dwarnings",
            "-O",
            "--crate-name",
            "sml_r6a",
        ])
        .arg(&file)
        .arg("-o")
        .arg(&binary)
        .stdin(Stdio::null())
        .output()?;
    if !result.status.success() {
        return Err(String::from_utf8_lossy(&result.stderr).into_owned().into());
    }
    let result = Command::new(&binary)
        .env_clear()
        .current_dir(root)
        .stdin(Stdio::null())
        .output()?;
    if !result.status.success()
        || !result.stderr.is_empty()
        || result.stdout.len() != 65_536 * TASKS
    {
        return Err("R6a compiled execution failed".into());
    }
    Ok(result.stdout)
}

pub fn examine(parent: &str, child: &str, bank: &str) -> Result<[u64; 4]> {
    let saved = memory(parent, child)?;
    let temp = Temp::new()?;
    let path = temp.0.join("r6.bank");
    fs::write(&path, bank)?;
    let programs = restore(&fs::read_to_string(path)?)?;
    let output = compile(&saved, &programs, &temp.0)?;
    let mut totals = [0; 4];
    for a in 0..=255u8 {
        for b in 0..=255u8 {
            let index = usize::from(a) * 256 + usize::from(b);
            let cohort = if TRAIN.contains(&(a, b)) {
                0
            } else if DEV.contains(&(a, b)) {
                1
            } else {
                2 + index % 2
            };
            for (task, program) in programs.iter().enumerate() {
                let expected = oracle(task, a, b);
                if program.eval(&saved, a, b) != expected
                    || output[index * TASKS + task] != expected
                {
                    return Err(format!("R6a exhaustive mismatch task={task}, a={a}, b={b}").into());
                }
                totals[cohort] += 1;
            }
        }
    }
    Ok(totals)
}

/// A local edit changes a single typed field, never the program family.
fn one_edit(a: Program, b: Program) -> bool {
    match (a, b) {
        (Program::Branch(p, y, n), Program::Branch(q, u, v)) => {
            usize::from(p != q) + usize::from(y != u) + usize::from(n != v) == 1
        }
        (Program::Repeat(n, f), Program::Repeat(m, g)) => {
            usize::from(n != m) + usize::from(f != g) == 1
        }
        (Program::Sequence(f, g), Program::Sequence(h, i)) => {
            usize::from(f != h) + usize::from(g != i) == 1
        }
        _ => false,
    }
}

fn neighborhood(initial: Program) -> Vec<Program> {
    grammar()
        .into_iter()
        .filter(|&p| p == initial || one_edit(initial, p))
        .collect()
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct RepairProposal {
    pub traces: Vec<Vec<crate::tutor_rust_r5::Action>>,
    pub candidate: Option<String>,
}

const REPAIR_BUDGET: usize = 8;

fn plan_local(
    saved: &[Expr],
    initial: Program,
    evidence: &[Example],
    budget: usize,
    adaptive: bool,
) -> Vec<crate::tutor_rust_r5::Action> {
    use crate::tutor_rust_r5::Action;
    let universe = neighborhood(initial);
    let mut remaining: Vec<usize> = (0..universe.len()).collect();
    let mut used = vec![false; evidence.len()];
    let mut trace = Vec::new();
    for step in 0..=budget {
        if remaining.len() == 1 {
            trace.push(Action::Patch {
                candidate: remaining[0],
            });
            return trace;
        }
        if remaining.is_empty() || step == budget {
            break;
        }
        let mut available = (0..evidence.len()).filter(|&i| !used[i]);
        let next = if adaptive {
            available
                .map(|i| {
                    let (a, b, _) = evidence[i];
                    let mut counts = [0usize; 256];
                    for &candidate in &remaining {
                        counts[usize::from(universe[candidate].eval(saved, a, b))] += 1;
                    }
                    (counts.iter().map(|n| n * n).sum::<usize>(), i)
                })
                .filter(|&(score, _)| score < remaining.len() * remaining.len())
                .min()
                .map(|(_, i)| i)
        } else {
            available.next()
        };
        let Some(index) = next else { break };
        let (a, b, observed) = evidence[index];
        used[index] = true;
        trace.push(Action::Probe { index, observed });
        remaining.retain(|&i| universe[i].eval(saved, a, b) == observed);
    }
    trace.push(Action::Abstain);
    trace
}

fn replay_local(
    saved: &[Expr],
    initial: Program,
    evidence: &[Example],
    budget: usize,
    trace: &[crate::tutor_rust_r5::Action],
) -> Result<Option<Program>> {
    use crate::tutor_rust_r5::Action;
    let universe = neighborhood(initial);
    let mut remaining: Vec<usize> = (0..universe.len()).collect();
    let mut used = vec![false; evidence.len()];
    let mut probes = 0;
    for (step, action) in trace.iter().enumerate() {
        match *action {
            Action::Probe { index, observed } => {
                let &(a, b, y) = evidence.get(index).ok_or("foreign R6b probe")?;
                if used[index] || probes >= budget || observed != y {
                    return Err("invalid R6b probe".into());
                }
                used[index] = true;
                probes += 1;
                remaining.retain(|&i| universe[i].eval(saved, a, b) == observed);
            }
            Action::Patch { candidate } => {
                if step + 1 != trace.len() || remaining.as_slice() != [candidate] {
                    return Err("unsupported R6b patch".into());
                }
                return Ok(Some(universe[candidate]));
            }
            Action::Abstain => {
                if step + 1 != trace.len() {
                    return Err("R6b abstention must terminate".into());
                }
                return Ok(None);
            }
        }
    }
    Err("R6b missing terminal action".into())
}

/// Proposal only: no clean bank, no held-out labels, no publication.
pub fn propose_repair(
    parent: &str,
    child: &str,
    damaged: &str,
    train: &str,
    budget: usize,
) -> Result<RepairProposal> {
    if budget > REPAIR_BUDGET {
        return Err("R6b budget exceeds policy".into());
    }
    let saved = memory(parent, child)?;
    let initial = restore(damaged)?;
    let admitted = admit(train)?;
    let traces: Vec<_> = initial
        .iter()
        .zip(&admitted)
        .map(|(&p, evidence)| plan_local(&saved, p, evidence, budget, true))
        .collect();
    let candidate = replay_bank(&saved, &initial, &admitted, budget, &traces)?;
    Ok(RepairProposal { traces, candidate })
}

fn replay_bank(
    saved: &[Expr],
    initial: &[Program],
    admitted: &[Vec<Example>],
    budget: usize,
    traces: &[Vec<crate::tutor_rust_r5::Action>],
) -> Result<Option<String>> {
    if traces.len() != TASKS || budget > REPAIR_BUDGET {
        return Err("R6b trace or budget contract".into());
    }
    let mut repaired = Vec::new();
    for ((&p, evidence), trace) in initial.iter().zip(admitted).zip(traces) {
        if let Some(selected) = replay_local(saved, p, evidence, budget, trace)? {
            repaired.push(selected);
        }
    }
    Ok((repaired.len() == TASKS).then(|| checkpoint(&repaired)))
}

pub fn verify_repair(
    parent: &str,
    child: &str,
    damaged: &str,
    train: &str,
    budget: usize,
    proposal: &RepairProposal,
) -> Result<()> {
    let saved = memory(parent, child)?;
    let initial = restore(damaged)?;
    let admitted = admit(train)?;
    let candidate = replay_bank(&saved, &initial, &admitted, budget, &proposal.traces)?;
    if candidate != proposal.candidate {
        return Err("R6b substituted candidate".into());
    }
    Ok(())
}

pub fn qualify_repair(parent: &str, child: &str, clean: &str, train: &str) -> Result<()> {
    use crate::tutor_rust_r5::Action;
    examine(parent, child, clean)?;
    let saved = memory(parent, child)?;
    let original = restore(clean)?;
    let admitted = admit(train)?;
    let mut mutations = 0;
    let mut harmful = 0;
    let mut adaptive_probes = 0;
    let mut sequential_probes = 0;
    let mut sequential_solved = 0;
    let mut combined = original.clone();
    for (task, (&p, evidence)) in original.iter().zip(&admitted).enumerate() {
        let mut selected = false;
        for damaged in neighborhood(p).into_iter().filter(|&q| q != p) {
            mutations += 1;
            if (0..=255u8)
                .all(|a| (0..=255u8).all(|b| damaged.eval(&saved, a, b) == p.eval(&saved, a, b)))
            {
                continue;
            }
            harmful += 1;
            if !selected {
                combined[task] = damaged;
                selected = true;
            }
            let adaptive = plan_local(&saved, damaged, evidence, REPAIR_BUDGET, true);
            let sequential = plan_local(&saved, damaged, evidence, REPAIR_BUDGET, false);
            let count = |trace: &[Action]| {
                trace
                    .iter()
                    .filter(|a| matches!(a, Action::Probe { .. }))
                    .count()
            };
            adaptive_probes += count(&adaptive);
            sequential_probes += count(&sequential);
            if replay_local(&saved, damaged, evidence, REPAIR_BUDGET, &adaptive)? != Some(p) {
                return Err("R6b local repair failed".into());
            }
            if replay_local(&saved, damaged, evidence, REPAIR_BUDGET, &sequential)? == Some(p) {
                sequential_solved += 1;
            }
        }
        if !selected {
            return Err("R6b task has no harmful mutation".into());
        }
    }
    if mutations != 44 {
        return Err("R6b mutation coverage changed".into());
    }
    let damaged = checkpoint(&combined);
    if examine(parent, child, &damaged).is_ok() {
        return Err("R6b damaged bank passed exam".into());
    }
    let abstained = propose_repair(parent, child, &damaged, train, 0)?;
    if abstained.candidate.is_some() {
        return Err("R6b zero-budget proposal succeeded".into());
    }
    let proposal = propose_repair(parent, child, &damaged, train, REPAIR_BUDGET)?;
    verify_repair(parent, child, &damaged, train, REPAIR_BUDGET, &proposal)?;
    let mut forged = proposal.clone();
    forged.candidate = Some(damaged.clone());
    if verify_repair(parent, child, &damaged, train, REPAIR_BUDGET, &forged).is_ok() {
        return Err("R6b forged proposal passed".into());
    }
    let repaired = proposal.candidate.ok_or("R6b abstained")?;
    if repaired != clean {
        return Err("R6b exact recovery failed".into());
    }
    let cases: u64 = examine(parent, child, &repaired)?.iter().sum();
    let retained_r2: u64 = r2::examine(parent)?.iter().sum();
    let retained_r3: u64 = r3::examine(parent, child)?.iter().sum();
    println!("SML_TUTOR_R6B=PASS mutations={mutations} harmful={harmful} repaired={harmful} adaptive_probes={adaptive_probes} sequential_probes={sequential_probes} sequential_solved={sequential_solved} exact_recovery=true forged_rejected=true zero_budget_abstained=true cases={cases} retained_r2={retained_r2} retained_r3={retained_r3}");
    Ok(())
}

fn read(path: &Path) -> Result<String> {
    let mut raw = String::new();
    fs::File::open(path)?.take(8193).read_to_string(&mut raw)?;
    if raw.len() > 8192 {
        return Err("R6a input too large".into());
    }
    Ok(raw)
}

fn qualify(
    parent: &str,
    child: &str,
    train: &str,
    source: &str,
    output: Option<&Path>,
) -> Result<()> {
    let bank = induce(parent, child, train)?;
    let totals = examine(parent, child, &bank)?;
    let retained_r2: u64 = r2::examine(parent)?.iter().sum();
    let retained_r3: u64 = r3::examine(parent, child)?.iter().sum();
    if let Some(path) = output {
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(path)?;
        file.write_all(bank.as_bytes())?;
        file.sync_all()?;
    }
    for (cohort, total) in ["train", "dev", "test", "testtest"].into_iter().zip(totals) {
        println!("SML_TUTOR_R6A_COHORT cohort={cohort} correct={total} total={total}");
    }
    println!("SML_TUTOR_R6A=PASS programs=4 grammar=196 macro_baseline_abstains=4 exact_cases={} retained_r2={retained_r2} retained_r3={retained_r3} source={source}", totals.iter().sum::<u64>());
    Ok(())
}

pub fn run_cli() -> Result<()> {
    let args: Vec<_> = std::env::args_os().skip(1).collect();
    match args.as_slice() {
        [] => {
            let parent = r2::induce(&r2::fixture())?;
            let child = r3::induce(&parent, &r3::fixture())?;
            qualify(&parent, &child, &fixture(), "synthetic_fixture", None)
        }
        [flag, parent, child, bank, train] if flag == "--repair-qualify" => qualify_repair(
            &read(Path::new(parent))?,
            &read(Path::new(child))?,
            &read(Path::new(bank))?,
            &read(Path::new(train))?,
        ),
        [flag, parent, child, train, output] if flag == "--teacher-train" => qualify(
            &read(Path::new(parent))?,
            &read(Path::new(child))?,
            &read(Path::new(train))?,
            "external_inputs",
            Some(Path::new(output)),
        ),
        _ => Err(
            "usage: sml_tutor_rust_r6 [--teacher-train r2.bank r3.bank r6.train r6.bank | --repair-qualify r2.bank r3.bank r6.bank r6.train]".into(),
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bounded_control_flow_compiles_and_retains_memory() {
        let parent = r2::induce(&r2::fixture()).unwrap();
        let child = r3::induce(&parent, &r3::fixture()).unwrap();
        let train = fixture();
        let bank = induce(&parent, &child, &train).unwrap();
        assert_eq!(restore(&bank).unwrap().len(), TASKS);
        assert!(bank.contains("if "));
        assert!(bank.contains("for _ in"));
        assert!(bank.contains("let x="));
        assert_eq!(
            examine(&parent, &child, &bank).unwrap().iter().sum::<u64>(),
            262_144
        );
        assert!(admit(&train.replacen("0|0|0|0", "0|0|0|1", 1)).is_err());
        assert!(restore("SML_TUTOR_R6A_BANK_V1\nunsafe{}\n").is_err());
        assert!(induce(&parent, "invalid", &train).is_err());
    }
    #[test]
    fn local_control_flow_mutations_are_repaired() {
        let parent = r2::induce(&r2::fixture()).unwrap();
        let child = r3::induce(&parent, &r3::fixture()).unwrap();
        let train = fixture();
        let clean = induce(&parent, &child, &train).unwrap();
        qualify_repair(&parent, &child, &clean, &train).unwrap();
    }
}
